const mongoose = require('mongoose');
const Booking = require('./models/Booking'); // Assuming Booking model is in models/Booking.js

exports.checkAvailability = async (checkInDate, checkOutDate, roomId) => {
  // Validate required fields
  if (!checkInDate || !checkOutDate || !roomId) {
    throw new Error("Missing required parameters: checkInDate, checkOutDate, roomId are required.");
  }

  // Convert dates to proper Date objects
  const checkIn = new Date(checkInDate);
  const checkOut = new Date(checkOutDate);

  // Validate date formats
  if (isNaN(checkIn.getTime()) || isNaN(checkOut.getTime())) {
    throw new Error("Invalid date formats provided.");
  }

  try {
    // Query the Booking model to find existing bookings within date range
    const existingBookings = await Booking.find({
      roomId: roomId,
      $or: [
        { checkInDate: { $lt: checkOut, $gte: checkIn } },
        { checkOutDate: { $gt: checkIn, $lte: checkOut } },
        { checkInDate: { $lte: checkIn }, checkOutDate: { $gte: checkOut } }
      ]
    });

    // Ensure no double booking
    if (existingBookings.length > 0) {
      return { available: false, message: "Room/service is already booked for these dates." };
    }

    // If no conflicting bookings found
    return { available: true, message: "Room/service is available for booking." };

  } catch (error) {
    // Handle database connection errors
    throw new Error("Database error: " + error.message);
  }
};

exports.manageTimeSlots = async ({ date, serviceId, availableSlots }) => {
  // Validate required fields
  if (!date || !serviceId || !Array.isArray(availableSlots) || availableSlots.length === 0) {
    throw new Error("Missing required parameters: date, serviceId, and availableSlots are required.");
  }

  // Convert date to a Date object
  const validDate = new Date(date);
  if (isNaN(validDate.getTime())) {
    throw new Error("Invalid date format provided.");
  }

  try {
    // Check for overlapping slots
    const overlappingSlots = await TimeSlot.find({
      serviceId: serviceId,
      date: validDate,
      time: { $in: availableSlots }
    });

    if (overlappingSlots.length > 0) {
      throw new Error("Some time slots are overlapping with existing bookings.");
    }

    // Create or update time slots
    await Promise.all(availableSlots.map(async (slot) => {
      await TimeSlot.updateOne(
        { serviceId: serviceId, date: validDate, time: slot },
        { $set: { serviceId, date: validDate, time: slot } },
        { upsert: true }
      );
    }));

    return { success: true, message: "Available time slots have been successfully managed." };

  } catch (error) {
    // Handle database errors
    throw new Error("Database error: " + error.message);
  }
};

